def getChatSetting(chat_tem) -> List[str]:
    """Try to load chat settings from StoryTemp by id; fall back otherwise."""
    from .models import StoryTemp

    try:
        if chat_tem is not None:
            story_id = int(chat_tem)
            story = StoryTemp.objects.filter(pk=story_id).first()
        else:
            story = None
    except (ValueError, TypeError):
        story = None

    if story:
        settings = [
            story.story_setting_1,
            story.story_setting_2,
            story.story_setting_3,
            story.story_setting_4,
            story.story_setting_5,
        ]
        TempArr = [s for s in settings if s]
        if TempArr:
            return TempArr

    return getChatSetting_fallback(chat_tem)


def extract_title(html_string: str) -> str:
    if not html_string:
        return ""

    match = re.search(r'<title[^>]*>(.*?)</title>', html_string, re.IGNORECASE | re.DOTALL)

    if match:
        return match.group(1).strip()

    plain_text = re.sub(r'<[^>]+>', '', html_string)
    
    plain_text = " ".join(plain_text.split())


    if len(plain_text) > 40:
        return plain_text[:40] + '...'
    
    return plain_text


def getDefaultReportPrompt():
    return """You are an expert in early childhood education and language development. Please read the following "story creation chat logs" between a child and the AI system.
Using a warm and encouraging tone, generate a "Creativity and Growth Observation Report" for the parents. You must strictly adhere to the following structure and absolutely must not include any psychological or medical diagnoses:
Imagination Highlights: Summarize the most fascinating story settings or characters the child created.
Language & Problem-Solving: List 3 or more excellent vocabulary words the child used, and describe how they navigated or solved challenges within their stories.
Emotion & Character Traits: Describe the positive traits the child demonstrated in their storytelling (e.g., bravery, helpfulness, curiosity).
Conversation Starters for Parents: Based on the story's content, provide 2 open-ended questions the parents can ask their child to foster engagement and strengthen their bond."""



def split_text_by_chars(text: str, num_parts: int = 5) -> list[str]:
    if not text:
        return [""] * num_parts
    
    total_chars = len(text)
    chars_per_part = total_chars // num_parts
    remainder = total_chars % num_parts
    
    result: list[str] = []
    start = 0
    
    for i in range(num_parts):
        end = start + chars_per_part + (1 if i < remainder else 0)
        chunk = text[start:end]         
        result.append(chunk)
        start = end
    
    return result